        title = self.title()
        title_url = QUrl(url)
        title_url.setScheme('')
        if title == title_url.toDisplayString(QUrl.RemoveScheme).strip('/'):
            title = ""
        if not url.isValid():
            log.misc.debug("Ignoring invalid URL being added to history")
