                "if",
                ["eq", left, ith_element],
                ["seq", ["mstore", found_ptr, found], "break"],
            ]
            loop = ["repeat", i, 0, len_, right.typ.count, loop_body]
            ret.append(
                [
                    "seq",
                    ["mstore", found_ptr, not_found],
                    loop,
                    ["mload", found_ptr],
