    return {
        "Qname": str(query.qname),
        "Qtype": rdatatype.to_text(query.rdtype),
        "Qclass": rdataclass.to_text(query.rdclass)
    }
def get_rrs_from_rrsets(rrsets):
    """This works for answer, authority, and additional rrsets"""
    rr_list = []
    for rrset in rrsets:
        common_rr_dict = {
            "Name":  str(rrset.name),
            "Type": rdatatype.to_text(rrset.rdtype),
            "Class": rdataclass.to_text(rrset.rdclass),
            "TTL": rrset.ttl
        }
        for rr in rrset:
            rr_dict = common_rr_dict.copy()
            rr_dict.update(get_record_specific_answer_fields(rr))
            rr_list.append(rr_dict)
    return rr_list
def is_valid_hostname(hostname):
    """Convert domain label into IDN ACE form (handles internationalized
    domains and regular (ascii) domains"""
    hostname = from_unicode(hostname).to_text()
    if len(hostname) > 255:
        return False
    if hostname[-1] == ".":
        hostname = hostname[:-1]
    allowed = re.compile("(?!-)[A-Z\d-]{1,63}(?<!-)$", re.IGNORECASE)
    return all(allowed.match(x) for x in hostname.split("."))
def is_valid_ip(ip):
    def is_valid_ipv4_address(address):
        try:
            socket.inet_pton(socket.AF_INET, address)
        except AttributeError:
            try:
                socket.inet_aton(address)
            except socket.error:
                return False
            return address.count('.') == 3
        except socket.error:
            return False
        return True
    def is_valid_ipv6_address(address):
        try:
            socket.inet_pton(socket.AF_INET6, address)
        except socket.error:
            return False
        return True
    return is_valid_ipv4_address(ip) or is_valid_ipv6_address(ip)
def is_valid_rdtype(rdtype):
    return rdtype in current_app.config['SUPPORTED_RDTYPES']

