_is_image_dataurl = re.compile(
    r'^data:image/.+;base64', re.I).search
_is_possibly_malicious_scheme = re.compile(
    r'(?:javascript|jscript|livescript|vbscript|data|about|mocha):',
    re.I).search
def _is_javascript_scheme(s):
    if _is_image_dataurl(s):
        return None
    return _is_possibly_malicious_scheme(s)
    def _remove_javascript_link(self, link):
        new = _substitute_whitespace('', unquote_plus(link))
        if _is_javascript_scheme(new):
            return ''
        return link

_find_image_dataurls = re.compile(
    r'^data:image/(.+);base64,', re.I).findall
_is_possibly_malicious_scheme = re.compile(
    r'(javascript|jscript|livescript|vbscript|data|about|mocha):',
    re.I).findall
_is_unsafe_image_type = re.compile(r"(xml|svg)", re.I).findall
def _is_javascript_scheme(s):
    is_image_url = False
    for image_type in _find_image_dataurls(s):
        is_image_url = True
        if _is_unsafe_image_type(image_type):
            return True
    if is_image_url:
        return False
    return bool(_is_possibly_malicious_scheme(s))
    def _remove_javascript_link(self, link):
        new = _substitute_whitespace('', unquote_plus(link))
        if _is_javascript_scheme(new):
            return ''
        return link

class RendererHTML(RendererProtocol):
    def renderToken(
        self,
        tokens: Sequence[Token],
        idx: int,
        options: OptionsDict,
        env: MutableMapping,
    ) -> str:
        """Default token renderer.
        Can be overridden by custom function
        :param idx: token index to render
        :param options: params of parser instance
        """
        result = ""
        needLf = False
        token = tokens[idx]
        if token.hidden:
            return ""
        if token.block and token.nesting != -1 and idx and tokens[idx - 1].hidden:
            result += "\n"
        result += ("</" if token.nesting == -1 else "<") + token.tag
        result += self.renderAttrs(token)
        if token.nesting == 0 and options["xhtmlOut"]:
            result += " /"
        if token.block:
            needLf = True
            if token.nesting == 1:
                if idx + 1 < len(tokens):
                    nextToken = tokens[idx + 1]
                    if nextToken.type == "inline" or nextToken.hidden:
                        needLf = False
                    elif nextToken.nesting == -1 and nextToken.tag == token.tag:
                        needLf = False
        result += ">\n" if needLf else ">"
        return result
    def renderInlineAsText(
        self,
        tokens: Sequence[Token] | None,
        options: OptionsDict,
        env: MutableMapping,
    ) -> str:
        """Special kludge for image `alt` attributes to conform CommonMark spec.
        Don't try to use it! Spec requires to show `alt` content with stripped markup,
        instead of simple escaping.
        :param tokens: list on block tokens to render
        :param options: params of parser instance
        :param env: additional data from parsed input
        """
        result = ""
        for token in tokens or []:
            if token.type == "text":
                result += token.content
            elif token.type == "image":
                assert token.children is not None
                result += self.renderInlineAsText(token.children, options, env)
            elif token.type == "softbreak":
                result += "\n"
        return result
    def image(
        self,
        tokens: Sequence[Token],
        idx: int,
        options: OptionsDict,
        env: MutableMapping,
    ) -> str:
        token = tokens[idx]
        assert (
            token.attrs and "alt" in token.attrs
        ), '"image" token\'s attrs must contain `alt`'
