class AbstractTab(QWidget):
    load_finished = pyqtSignal(bool)
    title_changed = pyqtSignal(str)
    load_status_changed = pyqtSignal(str)
    _insecure_hosts = set()
    def _set_load_status(self, val):
        """Setter for load_status."""
        if not isinstance(val, usertypes.LoadStatus):
            raise TypeError("Type {} is no LoadStatus member!".format(val))
        log.webview.debug("load status for {}: {}".format(repr(self), val))
        self._load_status = val
        self.load_status_changed.emit(val.name)
    def _on_predicted_navigation(self, url):
        """Adjust the title if we are going to visit an URL soon."""
        qtutils.ensure_valid(url)
        url_string = url.toDisplayString()
        log.webview.debug("Predicted navigation: {}".format(url_string))
        self.title_changed.emit(url_string)
    def _on_url_changed(self, url):
        """Update title when URL has changed and no title is available."""
        if url.isValid() and not self.title():
            self.title_changed.emit(url.toDisplayString())
        self.url_changed.emit(url)
        self._set_load_status(usertypes.LoadStatus.loading)
    def _on_load_finished(self, ok):
        if sip.isdeleted(self._widget):
            return
        sess_manager = objreg.get('session-manager')
        sess_manager.save_autosave()
        if ok:
            if self.url().scheme() == 'https':
                if self.url().host() in self._insecure_hosts:
                    self._set_load_status(usertypes.LoadStatus.warn)
                else:
                    self._set_load_status(usertypes.LoadStatus.success_https)
            else:
                self._set_load_status(usertypes.LoadStatus.success)
        elif ok:
            self._set_load_status(usertypes.LoadStatus.warn)
        else:
            self._set_load_status(usertypes.LoadStatus.error)
        self.load_finished.emit(ok)
        if not self.title():
            self.title_changed.emit(self.url().toDisplayString())
        self.zoom.set_current()
    def url(self, requested=False):
        raise NotImplementedError
    def title(self):
        raise NotImplementedError

class GlancesActions(object):
    def get(self, stat_name):
        """Get the stat_name criticity."""
        try:
            return self.status[stat_name]
        except KeyError:
            return None
    def set(self, stat_name, criticity):
        """Set the stat_name to criticity."""
        self.status[stat_name] = criticity
    def run(self, stat_name, criticity, commands, repeat, mustache_dict=None):
        """Run the commands (in background).
        - stats_name: plugin_name (+ header)
        - criticity: criticity of the trigger
        - commands: a list of command line with optional {{mustache}}
        - If True, then repeat the action
        - mustache_dict: Plugin stats (can be use within {{mustache}})
        Return True if the commands have been ran.
        """
        if (self.get(stat_name) == criticity and not repeat) or \
           not self.start_timer.finished():
            return False
        logger.debug("{} action {} for {} ({}) with stats {}".format(
            "Repeat" if repeat else "Run",
            commands, stat_name, criticity, mustache_dict))
        for cmd in commands:
            if chevron_tag:
                cmd_full = chevron.render(cmd, mustache_dict)
            else:
                cmd_full = cmd
            logger.info("Action triggered for {} ({}): {}".format(stat_name,
                                                                  criticity,
                                                                  cmd_full))
            logger.debug("Action will be executed with the following command: \
                subprocess.Popen({}, shell=False)".format(cmd_full.split(' ')))
            try:
                Popen(cmd_full.split(' '), shell=False)
            except OSError as e:
                logger.error("Can't execute the action ({})".format(e))
        self.set(stat_name, criticity)
        return True
    def __init__(self, config=None, args=None):
        self.config = config
        self.args = args
        self._quiet = args.quiet
        self.refresh_time = args.time
        start_duration = Counter()
        start_duration.reset()
        self.stats = GlancesStats(config=config, args=args)
        logger.debug("Plugins initialisation duration: {} seconds".format(start_duration.get()))
        if args.modules_list:
            self.display_modules_list()
            sys.exit(0)
        if not args.enable_process_extended:
            logger.debug("Extended stats for top process are disabled")
            glances_processes.disable_extended()
        else:
            logger.debug("Extended stats for top process are enabled")
            glances_processes.enable_extended()
        if args.process_filter is not None:
            glances_processes.process_filter = args.process_filter
        if (not WINDOWS) and args.no_kernel_threads:
            glances_processes.disable_kernel_threads()
        start_duration.reset()
        self.stats.update()
        logger.debug("First stats update duration: {} seconds".format(start_duration.get()))
        if self.quiet:
            logger.info("Quiet mode is ON, nothing will be displayed")
            glances_processes.max_processes = 0
        elif args.stdout_issue:
            logger.info("Issue mode is ON")
            self.screen = GlancesStdoutIssue(config=config, args=args)
        elif args.stdout:
            logger.info("Stdout mode is ON, following stats will be displayed: {}".format(args.stdout))
            self.screen = GlancesStdout(config=config, args=args)
        elif args.stdout_csv:
            logger.info("Stdout CSV mode is ON, following stats will be displayed: {}".format(args.stdout))
            self.screen = GlancesStdoutCsv(config=config, args=args)
        else:
            glances_processes.max_processes = 50
            self.screen = GlancesCursesStandalone(config=config, args=args)
        self.outdated = Outdated(config=config, args=args)
    def update(self):
        """Update sensors stats using the input method."""
        stats = self.get_init_value()
        if self.input_method == 'local':
            stats = []
            try:
                temperature = self.__set_type(self.glancesgrabsensors.get('temperature_core'),
                                              'temperature_core')
            except Exception as e:
                logger.error("Cannot grab sensors temperatures (%s)" % e)
            else:
                stats.extend(temperature)
            try:
                fan_speed = self.__set_type(self.glancesgrabsensors.get('fan_speed'),
                                            'fan_speed')
            except Exception as e:
                logger.error("Cannot grab FAN speed (%s)" % e)
            else:
                stats.extend(fan_speed)
            try:
                hddtemp = self.__set_type(self.hddtemp_plugin.update(),
                                          'temperature_hdd')
            except Exception as e:
                logger.error("Cannot grab HDD temperature (%s)" % e)
            else:
                stats.extend(hddtemp)
            try:
                batpercent = self.__set_type(self.batpercent_plugin.update(),
                                             'battery')
            except Exception as e:
                logger.error("Cannot grab battery percent (%s)" % e)
            else:
                stats.extend(batpercent)
        elif self.input_method == 'snmp':
            pass
        self.stats = self.get_init_value()
        for stat in stats:
            if self.is_hide(stat["label"].lower()):
                continue
            alias = self.has_alias(stat["label"].lower())
            if alias:
                stat["label"] = alias
            self.stats.append(stat)
        return self.stats
