    """
    Verify the ratelimit. By default return a 429 HTTP error code (Too Many Request).
    Usage:
    @cherrypy.tools.ratelimit(on=True, anonymous_limit=5, registered_limit=50, storage_class=FileRateLimit, storage_path='/tmp')
    def index(self):
        pass
