def glob_to_regex(glob):
    """Converts a glob to a compiled regex object.
    The regex is anchored at the beginning and end of the string.
    Args:
        glob (str)
    Returns:
        re.RegexObject
    """
    res = ""
    for c in glob:
        if c == "*":
            res = res + ".*"
        elif c == "?":
            res = res + "."
        else:
            res = res + re.escape(c)
    return re.compile(r"\A" + res + r"\Z", re.IGNORECASE)
